query:
NODE VALUE `incoming_degree` SumAgg<INT64> = 0
TABLE `results` { `id` STRING, `total` INT64 }

MATCH (`src`:`player`)-[`edge`:`follow`]->(`dst`:`player`)
PER PATH {
  SET `dst`.@`incoming_degree` += coalesce(`edge`.`degree`, 0)
}

MATCH (`p`:`player`)
PER NODE (`p`) {
  EXPORT `p`.`id`, `p`.@`incoming_degree` INTO `results`
}

FOR `row` IN `results`
RETURN `row`.`id` AS `id`, `row`.`total` AS `total`
